<?php require_once __DIR__.'/config/db.php';$page_title='Categories — MediNova';$cats=$pdo->query('SELECT c.*,COUNT(p.id) product_count FROM categories c LEFT JOIN products p ON p.category_id=c.id GROUP BY c.id ORDER BY c.name')->fetchAll();require __DIR__.'/includes/store_header.php';?><section class="page-hero"><p class="kicker">EXPLORE THE PHARMACY</p><h1>Care, <span>sorted.</span></h1><p>Choose a category and discover products curated for everyday health, wellness and personal care.</p></section><section class="content-section"><div class="service-cards"><?php foreach($cats as $i=>$c): ?><a class="service-card" href="shop.php?category=<?=e($c['slug'])?>" style="text-decoration:none;color:#fff"><span class="service-number">0<?=($i+1)?></span><h3><?=e($c['name'])?></h3><p style="color:#808980;line-height:1.7"><?=e($c['description']??'Quality pharmacy essentials.')?></p><span style="color:var(--acid);font-size:11px;letter-spacing:.1em"><?=$c['product_count']?> PRODUCTS →</span></a><?php endforeach; ?></div></section><?php require __DIR__.'/includes/store_footer.php'; ?>
